function initFilterBars(){document.querySelectorAll(".filter-bar").forEach(t=>{const e=t.querySelectorAll(".filter-btn"),a=t.getAttribute("data-target")||".filterable-item",l=document.querySelectorAll(a);e.forEach(t=>{t.addEventListener("click",()=>{e.forEach(t=>t.classList.remove("active")),t.classList.add("active");const a=t.getAttribute("data-filter");l.forEach(t=>{"all"===a||t.getAttribute("data-category")===a||t.classList.contains(a)?(t.style.display="",t.style.opacity="1",t.style.transform="scale(1)"):t.style.display="none"})})})})}document.addEventListener("DOMContentLoaded",()=>{initFilterBars()});